<script setup>
import { Head, Link } from '@inertiajs/vue3';
import { money } from '../../Support/cart.js';
defineProps({ orders: Object, signedIn: Boolean, directoryUrl: String });
const date = value => new Intl.DateTimeFormat('en-GB', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Jakarta' }).format(new Date(value));
const status = order => order.status === 'cancelled' ? 'Cancelled' : order.status === 'expired' ? 'Expired' : order.payment_method !== 'cash' && order.payment_status !== 'paid' ? 'Awaiting payment' : ({ received: 'Order received', preparing: 'Preparing', ready: order.method === 'pickup' ? 'Ready for pickup' : 'Ready for delivery', out_for_delivery: 'Out for delivery', completed: order.method === 'pickup' ? 'Collected' : 'Completed' })[order.status] || order.status;
</script>
<template><Head title="My orders"><meta name="robots" content="noindex, nofollow"/></Head><div class="min-h-screen bg-[#f5f2ec] text-[#504941]"><header class="border-b border-stone-200 bg-[#fffdf9]"><nav class="mx-auto flex max-w-4xl items-center justify-between gap-4 px-5 py-5 sm:px-8"><Link :href="directoryUrl" class="text-xl font-semibold">Rintis.</Link><Link :href="directoryUrl" class="rounded-full border border-stone-300 px-4 py-2.5 text-sm">Explore stores ↗</Link></nav></header><main class="mx-auto max-w-4xl px-5 py-10 sm:px-8"><p class="text-xs uppercase tracking-[.18em] text-stone-400">Your purchases</p><h1 class="mt-3 text-3xl font-semibold">My orders.</h1><p class="mt-3 text-sm leading-6 text-stone-500">{{ signedIn ? 'Orders placed while signed in, plus guest orders from this browser.' : 'Guest orders from this browser. No account needed.' }}</p><p class="mt-3 rounded-2xl border border-stone-200 bg-white px-4 py-3 text-xs leading-6 text-stone-500">Guest history uses a private browser cookie lasting up to 30 days after your latest visit. Clearing cookies or using another browser removes access to this guest list. Keep your private order links too.</p><div v-if="!orders.data.length" class="mt-7 rounded-3xl border border-dashed border-stone-300 bg-[#fffdf9] px-6 py-12 text-center"><h2 class="text-lg font-semibold">No orders here yet.</h2><p class="mt-3 text-sm text-stone-500">Your orders will appear here after checkout.</p><Link :href="directoryUrl" class="mt-6 inline-block rounded-full bg-[#504941] px-5 py-3 text-sm text-white">Explore stores →</Link></div><article v-for="order in orders.data" :key="order.reference" class="mt-6 overflow-hidden rounded-3xl border border-stone-200 bg-[#fffdf9]"><div class="flex flex-wrap items-start justify-between gap-4 border-b border-stone-100 px-5 py-5 sm:px-6"><div><h2 class="text-lg font-semibold">{{ order.storeName }}</h2><p class="mt-2 text-xs text-stone-500">{{ date(order.placedAt) }} · WIB</p><p class="mt-2 font-mono text-xs text-stone-400">{{ order.reference }}</p></div><span class="rounded-full px-3 py-2 text-xs font-medium" :class="order.status === 'ready' || order.status === 'completed' ? 'bg-[#edf2e7] text-[#60734c]' : 'bg-stone-100 text-stone-600'">{{ status(order) }}</span></div><div class="p-5 sm:p-6"><ul class="space-y-2 text-sm"><li v-for="(item,index) in order.items" :key="index">{{ item.quantity }} × {{ item.name }}</li></ul><div class="mt-5 flex flex-wrap items-center justify-between gap-4 border-t border-stone-100 pt-5"><div><p class="text-lg font-semibold">{{ money(order.total) }}</p><p class="mt-1 text-xs capitalize text-stone-500">{{ order.method }} · {{ order.payment_method === 'cash' ? 'Cash' : order.payment_method === 'qris' ? 'QRIS' : 'Bank transfer' }} · {{ order.payment_status === 'paid' ? 'Paid' : 'Unpaid' }}</p></div><Link :href="order.url" class="rounded-full bg-[#504941] px-5 py-3 text-sm font-medium text-white">View order →</Link></div></div></article><nav v-if="orders.prev_page_url || orders.next_page_url" aria-label="Order history pages" class="mt-7 flex items-center justify-between text-sm"><Link v-if="orders.prev_page_url" :href="orders.prev_page_url" class="rounded-full border border-stone-300 px-4 py-2">← Previous</Link><span v-else/><span class="text-xs text-stone-500">{{ orders.current_page }} / {{ orders.last_page }}</span><Link v-if="orders.next_page_url" :href="orders.next_page_url" class="rounded-full border border-stone-300 px-4 py-2">Next →</Link><span v-else/></nav></main></div></template>
